def step(i, sid, f, lbl, who):
    c, ic = AREA[sid.split('-')[0]]
    fg = '#FFFFFF' if c in ('#2F5BFF','#0B0B14','#9B7BFF') else OL
    return f'<a href="{f}" style="text-decoration: none; color: {T["tx"]}; flex: 0 0 200px; display: flex; flex-direction: column; gap: 10px; {A("up", .05*i)}"><div style="height: 130px; border-radius: 22px; background: {c}; border: 2px solid {OL}; position: relative; padding: 14px; box-sizing: border-box; display: flex; flex-direction: column; justify-content: space-between; color: {fg}"><span style="display: flex; justify-content: space-between; align-items: center"><span style="width: 32px; height: 32px; border-radius: 50%; background: #FFFFFF; color: {OL}; border: 2px solid {OL}; font-family: {HF}; font-weight: 800; display: inline-flex; align-items: center; justify-content: center; box-sizing: border-box">{i+1}</span>{icon(ic,24,fg,2.4)}</span><span style="font-family: {HF}; font-weight: 800; font-size: 14px">{e(sid)}</span></div><span style="font-size: 15px; font-weight: 800">{e(lbl)}</span><span style="font-size: 12.5px; color: {T["mu"]}">{e(who)} · open board →</span></a>'
arr = f'<span aria-hidden="true" style="flex: 0 0 auto; align-self: flex-start; margin-top: 52px; color: {T["mu"]}">{icon("arrowr",26)}</span>'
for jid, name, desc, steps_ in FLOWS:
    CUR['row'] = jid
    chain = arr.join(step(i, *s) for i, s in enumerate(steps_))
    body = f'<main style="padding: 48px; display: flex; flex-direction: column; gap: 24px">{row(sticker(jid,"#FFD43B",-4,"arrowr",14), chip(str(len(steps_))+" steps","neutral"), gap=12)}{big(name, 52)}{P(desc + " Every step opens its board. Press Play to click through.", size=17)}<div style="display: flex; gap: 14px; align-items: flex-start; overflow-x: auto; padding: 10px 4px 20px">{chain}</div></main>'
    write(f'Flow-{jid}.dc.html', doc(f'{jid} {name} (flow)', body, max(1440, 214*len(steps_)+96), 620))
    REG[f'Flow-{jid}.dc.html']['interactive'] = True
CUR['row'] = 'FLOWIDX'
cards = ''.join(f'<a href="Flow-{j}.dc.html" style="text-decoration: none; color: {OL}; border-radius: 28px; background: {["#FFD43B","#59D8FF","#B6F24A","#FF4FB8","#FF7A2F"][i%5]}; border: 2px solid {OL}; box-shadow: 5px 5px 0 {OL}; padding: 20px; display: flex; flex-direction: column; gap: 6px; {A("up",.03*i)}"><span style="font-family: {HF}; font-weight: 800; font-size: 14px">{j} · {len(s)} steps</span><span style="font-family: {HF}; font-weight: 800; font-size: 22px; line-height: 1.15">{e(n)}</span><span style="font-size: 13.5px">{e(d)}</span></a>' for i, (j, n, d, s) in enumerate(FLOWS))
write('Flows.dc.html', doc('Flow index', f'<main style="padding: 56px; display: flex; flex-direction: column; gap: 24px">{row(logo(30), sticker("Every flow","#FF4FB8",-4,"arrowr"), gap=14)}{big("15 flows, all clickable.", 60)}{P("Each card opens a step-by-step map. Every step links to its exact board (and state), and every board’s navigation links to the others, so Play mode walks the whole product.", size=17)}<div style="display: grid; grid-template-columns: repeat(auto-fill, minmax(320px, 1fr)); gap: 18px">{cards}</div></main>', 1440, 1400))
